/**
 * The terrain tiles' dissolve (tileFade.ts) as a material plugin: on every
 * material the view marks as a tile's, a pixel the mesh does not draw while
 * it fades is dropped. The fade is read per mesh as it is drawn, so tiles
 * that share a material fade each on their own. Code-split: a view fetches
 * it the first time tiles swap.
 */
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import type { UniformBuffer } from '@babylonjs/core/Materials/uniformBuffer';
import type { SubMesh } from '@babylonjs/core/Meshes/subMesh';
import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Engine } from '@babylonjs/core/Engines/engine';
import type { Scene } from '@babylonjs/core/scene';
import { selectTileFadeCode, type TileFade, type TileFadeHandle } from './tileFade';
import { materialArrivals } from './materialArrivals';

const PLUGIN_NAME = 'TileFade';

class TileFadePlugin extends MaterialPluginBase {
  private _isEnabled = true;

  constructor(
    material: ConstructorParameters<typeof MaterialPluginBase>[0],
    private readonly fadeOf: (mesh: AbstractMesh) => TileFade | undefined,
  ) {
    super(material, PLUGIN_NAME, 340, { TILEFADE: false }, true, true);
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'TileFadePlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0]): void {
    (defines as unknown as Record<string, boolean>)['TILEFADE'] = this._isEnabled;
  }

  override getUniforms(shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL) {
    const code = selectTileFadeCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    return {
      ubo: [
        { name: 'tileFadeThreshold', size: 1, type: 'float' },
        { name: 'tileFadeSide', size: 1, type: 'float' },
      ],
      fragment: code.uniforms,
    };
  }

  override bindForSubMesh(ubo: UniformBuffer, _scene: Scene, _engine: Engine, subMesh: SubMesh): void {
    if (!this._isEnabled) return;
    const f = this.fadeOf(subMesh.getMesh());
    ubo.updateFloat('tileFadeThreshold', f ? f.threshold : 1);
    ubo.updateFloat('tileFadeSide', f ? f.side : 0);
  }

  override getCustomCode(shaderType: string, shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL): { [pointName: string]: string } | null {
    if (shaderType !== 'fragment') return null;
    const code = selectTileFadeCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    return { CUSTOM_FRAGMENT_MAIN_BEGIN: `#ifdef TILEFADE\n${code.fragment}#endif\n` };
  }
}

export function createTileFadeOn(scene: Scene, o: { isTileMaterial: (m: object) => boolean; fadeOf: (mesh: AbstractMesh) => TileFade | undefined }): TileFadeHandle {
  const plugins: TileFadePlugin[] = [];
  const arrivals = materialArrivals(scene);
  // Not the materials there now: a plugin put on a material that has drawn rebuilds its shader, and the tiles it
  // draws are gone for the frames that takes. Only those that arrive from now on, before they first draw.
  arrivals.take(() => {});
  const attach = () =>
    arrivals.take((m) => {
      if (!o.isTileMaterial(m) || m.pluginManager?.getPlugin(PLUGIN_NAME)) return;
      const kind = m.getClassName();
      if (kind !== 'StandardMaterial' && kind !== 'PBRMaterial') return;
      plugins.push(new TileFadePlugin(m, o.fadeOf));
    });
  attach();
  return {
    update: attach,
    dispose() {
      arrivals.dispose();
      for (const p of plugins) p.isEnabled = false;
      plugins.length = 0;
    },
  };
}
